entries[188762] = { ["name"] = "Schwingende Stange", ["text"] = "\"Diese glitzernde, mit Runen versehene Stange summt, wenn sie angeklopft wird, und singt, wenn man über sie streicht.\"\nVerkaufspreis:" }
entries[188765] = { ["name"] = "Mittlerstudien", ["text"] = "Questgegenstand\n\"Dieses Gerät enthält die gesammelten Studien des verstorbenen Erleuchteten Mittlers.\"" }
entries[188766] = { ["name"] = "Resonator des kosmischen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Werft den kosmischen Resonator. Dieser explodiert nach 4 Sek. und verursacht 2039 kosmischen Schaden, der auf alle Gegner in der Nähe aufgeteilt wird.\n\nDer Schaden erhöht sich pro getroffenem Gegner, für bis zu 5 Gegner. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[188775] = { ["name"] = "Ewige Aegis des kosmischen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Aktiviert die Verteidigung und absorbiert für 15 Sek. 50% sämtlichen erlittenen Magieschadens, bis zu maximal [ 2339 * (1 + Vielseitigkeit)] Schaden. Kosmischer Schaden wird vollständig absorbiert. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[188778] = { ["name"] = "Verschlingende Verwünschung des kosmischen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 42 Vielseitigkeit\nBenutzen: Entzieht allen Gegnern in der Nähe im Verlauf von 3 Sek. bis zu ( 752 * 4) Absorption und entfesselt sie in einem kegelförmigen Bereich von 20 Metern vor Euch als heilende Absorption. (3 Min Abklingzeit)\nVerkaufspreis:" }
