entries[188789] = { ["name"] = "Bufonidenkehlschutz", ["text"] = "\"Ein filigranes Stück Metall, das sowohl der Nahrungsaufnahme als auch der Verteidigung dient.\"\nVerkaufspreis:" }
entries[188790] = { ["name"] = "Gegliederte Kugel", ["text"] = "\"Teile dieses Entwurfs sind an einer fixierten Achse ausgerichtet und erfüllen die Funktion mechanischer Gelenke, vermutlich für ein Automa.\"\nVerkaufspreis:" }
