entries[188793] = { ["name"] = "Verbessertes Chiffreanalysewerkzeug", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Erhöht dauerhaft von diesem Spielercharakter erhaltene Chiffren um 50%. Kann nur einmal per Spielercharakter genutzt werden.\n\"Die Chiffren der Ersten sind in Zereth Mortis allgegenwärtig. Wir können nicht alle für unsere sterblichen Augen sichtbar machen, doch hiermit werdet Ihr mehr von ihnen zu sehen bekommen.\"" }
entries[188794] = { ["name"] = "Eingefangenes Licht", ["text"] = "\"Spürbare Lichtpartikel, die sorglos im Wind flattern und über die Hügel von Zereth Mortis springen.\"\nVerkaufspreis:" }
entries[188795] = { ["name"] = "Majestätische Mähne", ["text"] = "\"Das Haar strahlt geweihte Energie aus und weckt Ehrfurcht.\"\nVerkaufspreis:" }
entries[188796] = { ["name"] = "Chiffretestgegenstand", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[188798] = { ["name"] = "Gestohlenes Artefakt", ["text"] = "Questgegenstand\nEinzigartig\n\"Allein das Berühren dieser seltsamen Kugel erweckt in Euch ein leichtes Gefühl der Verschiebung.\"" }
entries[188808] = { ["name"] = "Geduldiger Bufonid", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Einige Bufoniden können stunden- oder tagelang stillsitzen, wenn sie sich selbst überlassen werden. Glücklicherweise sind sie auch wohlgesonnen genug, um sich nicht darüber zu erregen, dass ein Reiter vielleicht häufiger ihre Dienste benötigt.\"\nQuest:\nDer geduldige Bufonid\nZone:\nZereth Mortis" }
entries[188809] = { ["name"] = "Hüpferprototyp", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein uralter Bauplan ermöglicht die Instanziierung dieses frühen, aber funktionalen Bufonidenentwurfs.\"\nBeruf:\nProtoformsynthese" }
entries[188810] = { ["name"] = "Rostroter Bufonid", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Rostrot ist eine seltene Farbe unter Bufoniden und wird normalerweise nur bei Exemplaren gefunden, die durch andere kosmische Kräfte verunreinigt oder durch einen verblüffenden Bauplan synthetisiert wurden, der diese Farbe hervorruft.\"\nBeruf:\nProtoformsynthese" }
entries[188811] = { ["name"] = "Erhabener Salzkristall", ["text"] = "\"Ein Blick in sein glasiges Inneres offenbart einen Ozean aus Sternen. Endlose Tiefen, grenzenlose Galaxien, ungeahnte Welten... Was?\"\nVerkaufspreis:" }
