entries[189171] = { ["name"] = "Schmuckstück der reinen Innovation", ["text"] = "Protoformsynthese\nWird an Kriegsmeute gebunden\nEinzigartig (2)\nHandwerksmaterial\n\"Innovation ist nichts anderes als Wahnsinn, der durch eine einzelne klare Vision nutzbar gemacht wird.\"\nVerkaufspreis:" }
entries[189172] = { ["name"] = "Kristallisiertes Echo des Ersten Lieds", ["text"] = "Protoformsynthese\nWird an Kriegsmeute gebunden\nEinzigartig (3)\nHandwerksmaterial\n\"Das Einzige, was von diesem lange vergessenen Lied verblieben ist, liegt im Plätschern fallenden Wassers verborgen.\"\nVerkaufspreis:" }
entries[189173] = { ["name"] = "Ewige Wutperle", ["text"] = "Protoformsynthese\nWird an Kriegsmeute gebunden\nEinzigartig (2)\nHandwerksmaterial\n\"Wenn alles in der Dunkelheit verloren geht, verbleibt nur noch die Wut.\"\nVerkaufspreis:" }
entries[189174] = { ["name"] = "Linse der fokussierten Absicht", ["text"] = "Protoformsynthese\nWird an Kriegsmeute gebunden\nEinzigartig (2)\nBenötigt Die Erleuchteten\n- Respektvoll\nHandwerksmaterial\n\"Durch diese Linse sehen die Erleuchteten die Wahrheit.\"\nVerkaufspreis:" }
entries[189175] = { ["name"] = "Schlundgeschmiedetes Zaumzeug", ["text"] = "Protoformsynthese\nWird an Kriegsmeute gebunden\nEinzigartig (3)\nHandwerksmaterial\n\"Flüchtige Synergien... oder Glück... ist alles, was Zovaal für seine Flucht aus dem Schlund brauchte.\"\nVerkaufspreis:" }
entries[189176] = { ["name"] = "Protoformempfindungskrone", ["text"] = "Protoformsynthese\nWird an Kriegsmeute gebunden\nEinzigartig (3)\nHandwerksmaterial\n\"Auf Eurem Kopf bringt sie Euch Sinn durch Dienst.\"\nVerkaufspreis:" }
entries[189177] = { ["name"] = "Offenbarungsschlüssel", ["text"] = "Protoformsynthese\nWird an Kriegsmeute gebunden\nEinzigartig (2)\nHandwerksmaterial\n\"Einige gefährliche Wahrheiten müssen zum Schutze der Sterblichen verborgen bleiben.\"\nVerkaufspreis:" }
entries[189178] = { ["name"] = "Werkzeuge unbegreiflicher Experimente", ["text"] = "Protoformsynthese\nWird an Kriegsmeute gebunden\nEinzigartig (3)\nHandwerksmaterial\n\"Ein Verstand ohnegleichen nutzt sie für... fehlerhafte Schöpfungen.\"\nVerkaufspreis:" }
entries[189179] = { ["name"] = "Unlegierter Bronzebarren", ["text"] = "Protoformsynthese\nWird an Kriegsmeute gebunden\nEinzigartig (2)\nHandwerksmaterial\n\"Wenn dies auf Welten Sterblicher in einem Lager entdeckt werden würde, könnte niemand den Unterschied zu normaler Bronze aus Kupfer und Zinn ausmachen.\"\nVerkaufspreis:" }
entries[189180] = { ["name"] = "Unendlicher Ruf des Windes", ["text"] = "Protoformsynthese\nWird an Kriegsmeute gebunden\nEinzigartig (2)\nHandwerksmaterial\n\"Jede ausreichend verbesserte Seele kann sich von den Winden von Zereth Mortis tragen lassen.\"\nVerkaufspreis:" }
