entries[189625] = { ["name"] = "10.0 Raid Template - Melee DPS - Trinket", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 [Beweglichkeit oder Stärke]\nBenutzen: Werdet 10 Sek. lang zum lauernden Raubtier, was Eure Geschwindigkeit um 278 erhöht. Ihr stürzt Euch außerdem auf den nächsten Gegner, der sich auf 8 Meter nähert, was ihm 19822 körperlichen Schaden zufügt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[189626] = { ["name"] = "10.0 Raid Template - Tank - Trinket", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 [Beweglichkeit oder Stärke]\nBenutzen: Geht für 30 Sek. ein Band des Jägersmanns mit dem anvisierten Verbündeten ein. 25% des von Euch erlittenen Schadens werden auf diesen Verbündeten umgeleitet, bis zu insgesamt [ 58281 * (1 + Vielseitigkeit)] Schaden. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[189627] = { ["name"] = "10.0 Raid Template - Int DPS - Trinket", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 Intelligenz\nBenutzen: Aktiviert den Seelenzünder und opfert bis zu 11037 Gesundheit im Verlauf von 15 Sek., um 'Lodernde Woge' zu ermächtigen.\n\nAktiviert ihn erneut, um 'Lodernde Woge' einzusetzen, was Gegnern in einem kegelförmigen Bereich von 40 Metern [ 7884 * (1 + Vielseitigkeit)] Feuerschaden zufügt, die gleichmäßig aufgeteilt werden, und abhängig davon, wie lang der Seelenzünder aktiv war, ihnen zusätzlich bis zu 40% Schaden zufügt.\n\nDer Schaden erhöht sich pro getroffenem Gegner, bis zu 5 Gegnern. (1 Min. Abklingzeit)\nVerkaufspreis:" }
entries[189628] = { ["name"] = "10.0 Raid Template - Healer - Trinket", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 Intelligenz\nBenutzen: Stärkt Euren Verbündeten mit einem Büschel Phönixfedern, das ihn nach 6 Sek. um [ 26603 * (1 + Vielseitigkeit)] Gesundheit heilt. Dieser Wert erhöht sich abhängig von der fehlenden Gesundheit des Ziels um bis zu 25%. Wenn Euer Verbündeter tödlichen Schaden erleidet, wird dieser Effekt sofort ausgelöst. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[189629] = { ["name"] = "10.0 Raid Template - STR - Trinket", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 Stärke\nAnlegen: Eure Schadensfähigkeiten haben eine hohe Chance, 595 körperlichen Schaden zu verursachen und Euch um 300% des verursachten Schadens zu heilen. Bei überschüssiger Heilung dieses Effekts fügt Ihr Gegnern in der Nähe im Verlauf von 15 Sek. [ 501 * 5 * (1 + Vielseitigkeit)] körperlichen Schaden zu, der auf die Gegner aufgeteilt wird. Dies unterdrückt jedoch den Lebensdiebstahleffekt.\n\nDer Schaden erhöht sich pro getroffenem Gegner, bis zu 5 Gegnern.\nVerkaufspreis:" }
entries[189630] = { ["name"] = "10.0 Raid Template - Omni - Trinket", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Vier Tanzpartner erscheinen in einer zufälligen Aufstellung um Euch herum. Jeder von ihnen gewährt Euch stapelbar 20 Sek. lang 163 Tempo und 91 Geschwindigkeit, wenn Ihr Euch zu ihm hinbewegt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[189631] = { ["name"] = "10.0 Raid Template - Physical DPS - Trinket", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 [Beweglichkeit oder Stärke]\nBenutzen: Eure nächsten 5 Schaden verursachenden Fähigkeiten rufen 'Kollabierte Psyche' hervor, was 3330 Schattenschaden verursacht und den durch 'Kollabierte Psyche' erlittenen Schaden des Ziels für 5 Sek. um 1% erhöht. Bis zu 25-mal stapelbar. (1.5s Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[189632] = { ["name"] = "10.0 Raid Template - AGI - Trinket", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 Beweglichkeit\nAnlegen: Wenn Eure prozentuale Gesundheit höher ist als die Eures Ziels, haben Eure Fähigkeiten eine sehr hohe Chance, [ 925 * (1 + Vielseitigkeit)] körperlichen Schaden zu verursachen.\n\nWenn Eure prozentuale Gesundheit niedriger ist als die Eures Ziels, haben Eure Fähigkeiten eine sehr hohe Chance, Euch um [ 1263 * (1 + Vielseitigkeit)] Gesundheit zu heilen.\nVerkaufspreis:" }
entries[189633] = { ["name"] = "10.0 Raid Template - INT - Trinket", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 Intelligenz\nAnlegen: Tretet dem blutroten Chor bei. Jede Minute schwillt Euer kritischer Trefferwert im Verlauf von 30 Sek. um ( 158 * 3) an, bevor er auf den normalen Wert zurücksinkt. Dieser Effekt erhöht sich pro Mitglied des blutroten Chors in Eurer Gruppe um 5%.\nVerkaufspreis:" }
