entries[189722] = { ["name"] = "Ambitionalischer Kristallsphäroid", ["text"] = "Herbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nDauer: 1 Stunde\nErhöht das Tempo um 5%.\nBenutzen: Verbraucht diesen Kristall, um seine Verstärkung vorübergehend zu erhalten.\nDieser Effekt hält 15 Min lang an. Funktioniert nur im Freien in den Schattenlanden oder in Oribos.\n\"Kann in Chiffrenausrüstung gesockelt werden.\"\nVerkaufspreis:" }
