entries[189750] = { ["name"] = "Totemfragment des Kreischerschwarms", ["text"] = "Questgegenstand\n\"Das Runenmuster der Harpyien ist im Gewirr der Krallenspuren nur schwer zu erkennen.\"" }
entries[189751] = { ["name"] = "Kükenfeder", ["text"] = "Questgegenstand\n\"Diese Feder ist äußerst widerstandsfähig und doch unglaublich leicht.\"" }
entries[189753] = { ["name"] = "Firim im Exil, Epilog", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Nachtrag: Überlegungen zur Fragilität aller Dinge.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[189754] = { ["name"] = "Genesisspindel", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n28 - 37 Schaden Geschwindigkeit 2.60\n(12.5 Schaden pro Sekunde)\n+129 Intelligenz\n+33 Ausdauer\nHaltbarkeit 110 / 110\nAnlegen: Ihr erhaltet alle 30 Sek. ' Ephemere Effusion ', sodass Euer nächster Einsatz eines passenden Heilzaubers verstärkt wird und seinem Ziel so genau das gewährt, was es braucht.\nVerkaufspreis:" }
entries[189755] = { ["name"] = "Fortialischer fluidischer Sphäroid", ["text"] = "Herbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nDauer: 1 Stunde\nBenutzen: Dieser Effekt absorbiert einen tödlichen Angriff und stellt dann stattdessen 25% Eurer maximalen Gesundheit wieder her.\n\nDieser Effekt kann nur einmal alle 10 Min. auftreten. Dieser Effekt dauert 15 Min. lang an. Funktioniert nur im Freien in den Schattenlanden oder in Oribos.\nVerkaufspreis:" }
entries[189756] = { ["name"] = "Toxialischer fluidischer Sphäroid", ["text"] = "Herbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nDauer: 1 Stunde\nBenutzen: Fügt bis zu 5 Gegnern innerhalb von 40 Metern alle 5 Sek. bis zu 6% der maximalen Gesundheit als Schaden zu. Elitegegner erleiden verringerten Schaden.\nDieser Effekt dauert 15 Min. lang an. Funktioniert nur im Freien in den Schattenlanden oder in Oribos.\nVerkaufspreis:" }
